import { CreateDateColumn, PrimaryGeneratedColumn, UpdateDateColumn } from 'typeorm';

/**
 * Columns shared by every table: a UUID primary key and the two audit timestamps.
 *
 * Timestamps are `timestamptz` so they are stored in UTC and never depend on
 * the session time zone.
 */
export abstract class BaseEntity {
  /** Primary key, generated by PostgreSQL (`gen_random_uuid()`). */
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  /** When the row was inserted. */
  @CreateDateColumn({ type: 'timestamptz' })
  createdAt!: Date;

  /** When the row was last updated. */
  @UpdateDateColumn({ type: 'timestamptz' })
  updatedAt!: Date;
}
